import{_ as t,o as i,c as s,ah as a}from"./chunks/framework.D4KxWb5R.js";const c=JSON.parse('{"title":"Pages du site","description":"","frontmatter":{},"headers":[],"relativePath":"guide/administration/site-pages.md","filePath":"src/guide/administration/site-pages.md"}'),r={name:"guide/administration/site-pages.md"};function d(n,e,o,l,u,p){return i(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="pages-du-site" tabindex="-1">Pages du site <a class="header-anchor" href="#pages-du-site" aria-label="Permalink to &quot;Pages du site&quot;">​</a></h1><p><strong>Administration → Pages du site</strong> modifie le contenu du site public, sans développement. Ouvert au PDG et au Pôle Support Partenaires &amp; Clients.</p><h2 id="les-pages" tabindex="-1">Les pages <a class="header-anchor" href="#les-pages" aria-label="Permalink to &quot;Les pages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Contenu</th></tr></thead><tbody><tr><td>Général</td><td>En-tête et pied de page : nom, accroche, identité légale, adresse, e-mail, téléphone, réseaux sociaux</td></tr><tr><td>Accueil</td><td>Titre, introduction, piliers, sections produits et zones, appels à l&#39;action, questions fréquentes</td></tr><tr><td>Qui sommes-nous</td><td>Vision, mission, valeurs, ancrage régional, identité légale</td></tr><tr><td>Nos produits</td><td>Introduction de la liste des produits, carte « Prochain produit »</td></tr><tr><td>Nos zones</td><td>Approche, méthode, note sous les zones</td></tr><tr><td>Prestations, Partenaires</td><td>Éléments, étapes, types de partenariats</td></tr><tr><td>Presse &amp; kit média</td><td>Présentation, chiffres, éléments de langage, logo, kit média, contact presse</td></tr><tr><td>Carrières</td><td>Culture, offres d&#39;emploi, comment postuler</td></tr><tr><td>Contact</td><td>Texte au-dessus du formulaire, message de confirmation</td></tr><tr><td>Mentions légales, Politique de confidentialité, CGU</td><td>Sections du texte, date de mise à jour</td></tr></tbody></table><p>Les landing pages des produits ne sont pas ici : leur contenu se saisit sur la fiche du produit, dans le <a href="./registry.html#enregistrer-un-produit">registre</a>. La page « Nos zones » liste les zones qualifiées du registre.</p><h2 id="modifier-une-page" tabindex="-1">Modifier une page <a class="header-anchor" href="#modifier-une-page" aria-label="Permalink to &quot;Modifier une page&quot;">​</a></h2><ol><li>Ouvrez la page dans la liste. La liste indique la dernière modification et son auteur ; <strong>Voir sur le site</strong> ouvre la page publique.</li><li>Choisissez la <strong>langue d&#39;édition</strong>. L&#39;anglais est nécessaire pour qu&#39;un texte s&#39;affiche ; le français reprend l&#39;anglais s&#39;il est vide.</li><li>Modifiez les champs. Dans une liste (piliers, offres, questions…), ajoutez, retirez ou réordonnez les éléments.</li><li>Enregistrez.</li></ol><p>La modification est en ligne immédiatement et inscrite au <a href="./logs.html">journal d&#39;administration</a>.</p>',8)])])}const m=t(r,[["render",d]]);export{c as __pageData,m as default};
